exec('''"""СКРИПТ: Настройки/Конфигурация приложенияLINESPLITTER - Управление глобальными переменнымиLINESPLITTER - Объявление константLINESPLITTER - Менеджмент асетов и других ресурсов"""LINESPLITTERLINESPLITTER# -- импорт модулейLINESPLITTERimport gzipLINESPLITTERimport jsonLINESPLITTERimport osLINESPLITTERimport sysLINESPLITTERimport timeLINESPLITTERfrom dataclasses import dataclassLINESPLITTERfrom pathlib import PathLINESPLITTERfrom typing import OptionalLINESPLITTERLINESPLITTERimport arcadeLINESPLITTERimport pygletLINESPLITTERLINESPLITTERimport utilities as uLINESPLITTERfrom views import introLINESPLITTERLINESPLITTERLINESPLITTER# === КЛАССЫ БЫСТРОГО ДОСТУПА К РЕСУРСАМ ===LINESPLITTER# -- менеджер путейLINESPLITTERclass PathConfig:LINESPLITTER    def __init__(self, data_file: Path, asset_folder: Path, shader_folder: Path):LINESPLITTER        self.supported_ext = [\'.png\', \'.jpg\', \'.jpeg\', \'.ico\', \'.json\', \'.mp3\', \'.wav\', \'.ogg\', \'.otf\']LINESPLITTERLINESPLITTER        # основные путиLINESPLITTER        self.data_file = data_fileLINESPLITTER        self.asset_folder = asset_folderLINESPLITTER        self.shader_folder = shader_folderLINESPLITTERLINESPLITTER        # ярлыки обращения к ресурсамLINESPLITTER        self.shortcuts = {LINESPLITTER            \'icon\': self.asset_folder / Path(\'images/icons\'),LINESPLITTER            \'effect\': self.asset_folder / Path(\'sounds/effects\'),LINESPLITTER            \'music\': self.asset_folder / Path(\'sounds/music\'),LINESPLITTER            \'texture\': self.asset_folder / Path(\'images/textures\'),LINESPLITTER            \'font\': self.asset_folder / Path(\'fonts/\')LINESPLITTER        }LINESPLITTERLINESPLITTER        # определение системы сборкиLINESPLITTER        if getattr(sys, \'frozen\', False) and hasattr(sys, \'_MEIPASS\'):LINESPLITTER            os.chdir(sys._MEIPASS)LINESPLITTERLINESPLITTER    # - метод поиска файла в директорииLINESPLITTER    def get(self, folder: Path, name: str | Path) -> Optional[Path]:LINESPLITTER        path = folder / Path(name)LINESPLITTERLINESPLITTER        if not path.exists():LINESPLITTER            for i in self.supported_ext:LINESPLITTER                path = folder / Path(name + i)LINESPLITTER                if path.exists():LINESPLITTER                    return pathLINESPLITTERLINESPLITTER        return NoneLINESPLITTERLINESPLITTER    # - доступ к ярлыкамLINESPLITTER    def short(self, short: str, name: str | Path) -> Path:LINESPLITTER        return self.get(self.shortcuts[short], name)LINESPLITTERLINESPLITTERLINESPLITTER# -- подгрузка асетовLINESPLITTERclass AssetsConfig:LINESPLITTER    def __init__(self, paths: PathConfig):LINESPLITTER        self.paths = pathsLINESPLITTER        self._cache = {}LINESPLITTERLINESPLITTER    # - получение иконкиLINESPLITTER    def icon(self, name: str) -> pyglet.image.AbstractImage:LINESPLITTER        cache_key = f"icon:{name}"LINESPLITTERLINESPLITTER        if cache_key not in self._cache:LINESPLITTER            image_path = self.paths.short(\'icon\', name)LINESPLITTER            self._cache[cache_key] = pyglet.image.load(str(image_path))LINESPLITTERLINESPLITTER        return self._cache[cache_key]LINESPLITTERLINESPLITTER    # - получение музыкиLINESPLITTER    def music(self, name: str, streaming: bool = True) -> arcade.Sound:LINESPLITTER        cache_key = f"music:{name}:{streaming}"LINESPLITTERLINESPLITTER        if cache_key not in self._cache:LINESPLITTER            music_path = self.paths.short(\'music\', name)LINESPLITTER            self._cache[cache_key] = arcade.load_sound(music_path, streaming=streaming)LINESPLITTERLINESPLITTER        return self._cache[cache_key]LINESPLITTERLINESPLITTER    # - получение звукового эффектаLINESPLITTER    def effect(self, name: str, streaming: bool = True) -> arcade.Sound:LINESPLITTER        cache_key = f"effect:{name}:{streaming}"LINESPLITTERLINESPLITTER        if cache_key not in self._cache:LINESPLITTER            effect_path = self.paths.short(\'effect\', name)LINESPLITTER            self._cache[cache_key] = arcade.load_sound(effect_path, streaming=streaming)LINESPLITTERLINESPLITTER        return self._cache[cache_key]LINESPLITTERLINESPLITTER    # - получение текстурыLINESPLITTER    def texture(self, name: str, hitbox_algo=None) -> arcade.Texture:LINESPLITTER        cache_key = f"texture:{name}"LINESPLITTERLINESPLITTER        if cache_key not in self._cache:LINESPLITTER            self._cache[cache_key] = arcade.load_texture(self.paths.short(\'texture\', name),LINESPLITTER                                                         hit_box_algorithm=hitbox_algo)LINESPLITTERLINESPLITTER        return self._cache[cache_key]LINESPLITTERLINESPLITTER    # - получение шрифтаLINESPLITTER    def font(self, name: str) -> str:LINESPLITTER        cache_key = f"font:{name}"LINESPLITTERLINESPLITTER        if cache_key not in self._cache:LINESPLITTER            font_path = self.paths.short(\'font\', name)LINESPLITTER            arcade.load_font(font_path)LINESPLITTER            self._cache[cache_key] = font_pathLINESPLITTERLINESPLITTER        return self._cache[cache_key]LINESPLITTERLINESPLITTERLINESPLITTER# -- обработка сохраненийLINESPLITTERclass DataConfig:LINESPLITTER    def __init__(self, paths):LINESPLITTER        self.paths = pathsLINESPLITTER        self.data = {}LINESPLITTER        self.load_data()LINESPLITTERLINESPLITTER    # - создание целевой директорииLINESPLITTER    def prepare(self):LINESPLITTER        self.paths.data_file.parent.mkdir(parents=True, exist_ok=True)LINESPLITTERLINESPLITTER        if not self.paths.data_file.exists():LINESPLITTER            self.save_data()LINESPLITTERLINESPLITTER    # - загрузка данных, распаковкаLINESPLITTER    def load_data(self):LINESPLITTER        self.prepare()LINESPLITTERLINESPLITTER        try:LINESPLITTER            with gzip.open(self.paths.data_file, "rt", encoding="utf-8") as f:LINESPLITTER                self.data = json.load(f)LINESPLITTER                returnLINESPLITTER        except Exception as e:LINESPLITTER            try:LINESPLITTER                with self.paths.data_file.open("r", encoding="utf-8") as f:LINESPLITTER                    self.data = json.load(f)LINESPLITTER                self.save_data()LINESPLITTER            except Exception as e:LINESPLITTER                self.data = {}LINESPLITTER                returnLINESPLITTERLINESPLITTER    # - сохранение данныхLINESPLITTER    def save_data(self):LINESPLITTER        tmp = self.paths.data_file.with_suffix(".tmp")LINESPLITTERLINESPLITTER        with gzip.open(tmp, "wt", encoding="utf-8", compresslevel=9) as f:LINESPLITTER            json.dump(LINESPLITTER                self.data,LINESPLITTER                f,LINESPLITTER                ensure_ascii=False,LINESPLITTER                separators=(",", ":"),LINESPLITTER            )LINESPLITTERLINESPLITTER        tmp.replace(self.paths.data_file)LINESPLITTERLINESPLITTERLINESPLITTER# -- управление воспроизведением музыкиLINESPLITTERclass MusicConfig:LINESPLITTER    def __init__(self, assets: AssetsConfig):LINESPLITTER        self.assets = assetsLINESPLITTERLINESPLITTER        self.playing_name = \'\'LINESPLITTER        self.music = NoneLINESPLITTER        self._effects_cache = {}LINESPLITTERLINESPLITTER    # -- выключение предыдущей музыки, если нужна другая, запуск следующейLINESPLITTER    def ensure_playing(self, name, loop=True):LINESPLITTER        if self.playing_name == name:LINESPLITTER            returnLINESPLITTER        if self.music:LINESPLITTER            arcade.stop_sound(self.music)LINESPLITTER        self.playing_name = nameLINESPLITTER        self.music = arcade.play_sound(self.assets.music(name), loop=loop, volume=0.3)LINESPLITTERLINESPLITTER    def ensure_music_stopped(self):LINESPLITTER        if self.music:LINESPLITTER            arcade.stop_sound(self.music)LINESPLITTER            self.music = NoneLINESPLITTER            self.playing_name = \'\'LINESPLITTERLINESPLITTER    # -- звуковые эффекты с простым кэшированиемLINESPLITTER    def play_sound(self, name):LINESPLITTER        if name not in self._effects_cache:LINESPLITTER            effect = self.assets.effect(name, streaming=False)LINESPLITTER            self._effects_cache[name] = effectLINESPLITTER        else:LINESPLITTER            effect = self._effects_cache[name]LINESPLITTERLINESPLITTER        return arcade.play_sound(effect), effectLINESPLITTERLINESPLITTERLINESPLITTER# === ХРАНЕНИЕ ДАННЫХ ===LINESPLITTER# -- класс настроекLINESPLITTER@dataclassLINESPLITTERclass Config:LINESPLITTER    # - константыLINESPLITTER    # параметры окнаLINESPLITTER    WINDOW_WIDTH = 600LINESPLITTER    WINDOW_HEIGHT = 400LINESPLITTER    WINDOW_RESIZABLE = TrueLINESPLITTER    WINDOW_NAME = \'Окно в мир\'LINESPLITTERLINESPLITTER    WINDOW_MINIMAL_WIDTH = 200LINESPLITTER    WINDOW_MINIMAL_HEIGHT = 200LINESPLITTERLINESPLITTER    WINDOW_ICON = \'window_icon\'LINESPLITTERLINESPLITTER    # сцена запускаLINESPLITTER    LAUNCH_VIEW = intro.MainLINESPLITTERLINESPLITTER    # путиLINESPLITTER    DATA_FILE = Path(\'saves/save.json\')LINESPLITTER    ASSETS_FOLDER = Path(\'assets\')LINESPLITTER    SHADER_FOLDER = Path(\'shaders\')LINESPLITTERLINESPLITTER    # пользовательский вводLINESPLITTER    KEYS = {\'fullscreen\': arcade.key.F11,LINESPLITTER            \'move_up\': arcade.key.W,LINESPLITTER            \'move_down\': arcade.key.S,LINESPLITTER            \'move_left\': arcade.key.A,LINESPLITTER            \'move_right\': arcade.key.D,LINESPLITTER            \'zoom_in\': arcade.key.UP,LINESPLITTER            \'zoom_out\': arcade.key.DOWN,LINESPLITTER            \'action\': arcade.key.SPACE,LINESPLITTER            \'escape\': arcade.key.ESCAPE}LINESPLITTERLINESPLITTER    # вспомогательный флаг отладкиLINESPLITTER    DEBUG = FalseLINESPLITTERLINESPLITTER    # доступные сложностиLINESPLITTER    DIFFICULTIES = [\'Прогулка\', \'Приключение\', \'Пытка\', \'Шашлыки\']LINESPLITTERLINESPLITTER    CUSTOM_CURSOR = TrueLINESPLITTERLINESPLITTER    # - динамические модулиLINESPLITTER    # быстрый доступ к ресурсамLINESPLITTER    paths: PathConfig = PathConfig(DATA_FILE, ASSETS_FOLDER, SHADER_FOLDER)LINESPLITTER    assets: AssetsConfig = AssetsConfig(paths)LINESPLITTER    data: DataConfig = DataConfig(paths)LINESPLITTER    music: MusicConfig = MusicConfig(assets)LINESPLITTER    logger = u.archive_logging.Logger()LINESPLITTER    utils = uLINESPLITTERLINESPLITTER    player = NoneLINESPLITTER    enemy = NoneLINESPLITTERLINESPLITTER    start_time = time.time()LINESPLITTERLINESPLITTER    current_world = 0LINESPLITTERLINESPLITTER    logger.log(LINESPLITTER        f\'Настройки заданы. Базовые модули функционируют. Файл сохранения содержит {len(data.data)} аттрибута(ов)\')LINESPLITTER'''.replace('LINESPLITTER', '\n'))